import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color('#8bbcc2');scene.fog=new THREE.FogExp2('#8bbcc2',.00135);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,2600);camera.position.set(0,12,-20);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc9f0ee,0x426957,2.1));const sun=new THREE.DirectionalLight(0xffe5b3,3.2);sun.position.set(-180,260,-120);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-160;sun.shadow.camera.right=160;sun.shadow.camera.top=160;sun.shadow.camera.bottom=-160;scene.add(sun);
const mat=(color,roughness=.85)=>new THREE.MeshStandardMaterial({color,roughness});
const waterMat=new THREE.MeshStandardMaterial({color:0x187d83,roughness:.36,metalness:.08,flatShading:true});
const waterGeo=new THREE.PlaneGeometry(2600,2600,100,100);waterGeo.rotateX(-Math.PI/2);const water= new THREE.Mesh(waterGeo,waterMat);water.position.y=-.55;water.receiveShadow=true;scene.add(water);const waterBase=waterGeo.attributes.position.array.slice();
const wood=mat('#68452f'),darkWood=mat('#3b3028'),canvas=mat('#e6d6b5'),red=mat('#9a4639'),goldMat=mat('#c99e56'),leaf=mat('#39785a'),sand=mat('#c7a773'),grass=mat('#647d4d'),rockMat=mat('#777f75');
function box(parent,w,h,d,m,x=0,y=0,z=0){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function cylinder(parent,rt,rb,h,m,x,y,z,segments=8){const o=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function makeShip({enemy=false}={}){const g=new THREE.Group();const hullMat=enemy?mat('#514540'):wood;const stations=[[-2.65,.05,.22],[-2.15,.72,.36],[1.45,.78,.38],[2.65,.08,.28]];const verts=[],idx=[];for(const [z,w,h] of stations){verts.push(-w,-h,z,w,-h,z,-w,.22,z,w,.22,z)}for(let i=0;i<stations.length-1;i++){let a=i*4,b=(i+1)*4;idx.push(a,b,a+2,a+2,b,b+2,a+1,a+3,b+1,a+3,b+3,b+1,a+2,b+2,a+3,a+3,b+2,b+3)}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geo.setIndex(idx);geo.computeVertexNormals();const hull=new THREE.Mesh(geo,hullMat);hull.material.side=THREE.DoubleSide;hull.castShadow=true;hull.receiveShadow=true;g.add(hull);box(g,1.38,.13,3.9,enemy?darkWood:goldMat,0,.2,-.12);box(g,1.1,.55,.72,wood,0,.5,-1.62);box(g,.84,.18,.72,darkWood,0,.82,-1.62);
const mast=cylinder(g,.065,.09,4,wood,0,2.12,-.15,7);mast.rotation.z=-.035;const sailGeo=new THREE.PlaneGeometry(2.2,2.35,1,1);const sail=new THREE.Mesh(sailGeo,enemy?mat('#86483f',.95):canvas);sail.position.set(0,2.52,-.1);sail.castShadow=true;g.add(sail);const spar=cylinder(g,.045,.045,2.5,darkWood,0,3.8,-.1,6);spar.rotation.z=Math.PI/2;const flag=new THREE.Mesh(new THREE.PlaneGeometry(.72,.38),enemy?red:mat('#a54e3e'));flag.position.set(.4,4.06,-.15);flag.rotation.y=Math.PI/2;g.add(flag);for(const x of [-.57,.57]){cylinder(g,.045,.045,.2,darkWood,x,.42,.4,6);const cannon=cylinder(g,.12,.12,.38,darkWood,x,.5,.4,8);cannon.rotation.x=Math.PI/2}if(!enemy){const rail=box(g,1.62,.12,.12,goldMat,0,.39,.91);rail.rotation.x=0;g.userData.bob=0;}return g}
const player=makeShip();player.position.set(0,0,0);scene.add(player);
function addIsland(x,z,r,name){const g=new THREE.Group();g.position.set(x,-.25,z);scene.add(g);const base=new THREE.Mesh(new THREE.SphereGeometry(r,20,10),sand);base.scale.set(1,.17,.82);base.position.y=-.1;base.castShadow=true;base.receiveShadow=true;g.add(base);const mound=new THREE.Mesh(new THREE.SphereGeometry(r*.82,18,9),grass);mound.scale.set(1,.17,.79);mound.position.y=.24;mound.castShadow=true;mound.receiveShadow=true;g.add(mound);for(let i=0;i<8;i++){const a=i*2.4,radius=r*(.25+Math.random()*.42),tx=Math.cos(a)*radius,tz=Math.sin(a)*radius*.8;const trunk=cylinder(g,.13,.22,2.35,wood,tx,1.1,tz,7);trunk.rotation.z=(Math.random()-.5)*.24;for(let j=0;j<5;j++){let frond=new THREE.Mesh(new THREE.ConeGeometry(.3,2.35,5),leaf);frond.position.set(tx+Math.cos(j*1.25)*.74,2.15+Math.sin(j)*.18,tz+Math.sin(j*1.25)*.74);frond.rotation.z=Math.cos(j*1.25)*.85;frond.rotation.x=Math.sin(j*1.25)*.8;frond.scale.set(.65,1,.65);frond.castShadow=true;g.add(frond)}const coc=new THREE.Mesh(new THREE.SphereGeometry(.18,7,5),mat('#d1a651'));coc.position.set(tx,2.15,tz);g.add(coc)}for(let i=0;i<9;i++){let a=i*2.1;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.55+Math.random()*.65,0),rockMat);rock.position.set(Math.sin(a)*r*.74,.28,Math.cos(a)*r*.61);rock.scale.y=.7;rock.castShadow=true;g.add(rock)}g.userData.radius=r;g.userData.name=name;return g}
const cay=addIsland(300,-300,47,'Ember Cay');addIsland(-360,-170,62,'Driftwood Isle');addIsland(500,260,76,'Gull Rock');addIsland(-570,380,55,'Morrow Key');
function cloud(x,y,z,s){const g=new THREE.Group();g.position.set(x,y,z);for(let i=0;i<5;i++){const c=new THREE.Mesh(new THREE.SphereGeometry(s*(.55+Math.random()*.35),9,7),new THREE.MeshBasicMaterial({color:0xe1e9da,transparent:true,opacity:.32,depthWrite:false}));c.position.set((i-2)*s*.48,(Math.random()-.5)*s*.2,Math.random()*s*.24);c.scale.y=.34;g.add(c)}scene.add(g)}for(let i=0;i<14;i++)cloud((Math.random()-.5)*1300,95+Math.random()*55,(Math.random()-.5)*1100,12+Math.random()*21);
const enemy=makeShip({enemy:true});enemy.position.set(120,.12,-128);enemy.rotation.y=.72;scene.add(enemy);let enemyHP=4;
const projectiles=[];let gold=120,health=100,speed=0,yaw=0,started=false,won=false,cooldown=0,enemyCooldown=2,toastTimer=0;const keys={};
function notify(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.6}
function fireCannon(){if(!started||cooldown>0)return;cooldown=.48;const forward=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));const p=new THREE.Mesh(new THREE.SphereGeometry(.22,8,7),new THREE.MeshStandardMaterial({color:0xffd18a,emissive:0xc46b25,emissiveIntensity:1.5}));p.position.copy(player.position).addScaledVector(forward,3).add(new THREE.Vector3(0,.35,0));scene.add(p);projectiles.push({mesh:p,vel:forward.multiplyScalar(40),life:2.1,enemy:false});}
function enemyFire(){const d=new THREE.Vector3().subVectors(player.position,enemy.position);d.y=0;d.normalize();const p=new THREE.Mesh(new THREE.SphereGeometry(.19,7,6),new THREE.MeshStandardMaterial({color:0xff9868,emissive:0x9c3218,emissiveIntensity:1.4}));p.position.copy(enemy.position).addScaledVector(d,3).add(new THREE.Vector3(0,.35,0));scene.add(p);projectiles.push({mesh:p,vel:d.multiplyScalar(27),life:3,enemy:true})}
function start(){if(started)return;started=true;document.querySelector('#intro').classList.add('hide');notify('The wind is yours, Captain. Find Ember Cay.');}
document.querySelector('#play').addEventListener('click',start);document.querySelector('#game').addEventListener('pointerdown',()=>{if(!started)start()});document.querySelector('#fire').addEventListener('pointerdown',e=>{e.preventDefault();fireCannon()});document.querySelector('#boost').addEventListener('pointerdown',e=>{e.preventDefault();keys.Shift=true});document.querySelector('#boost').addEventListener('pointerup',()=>keys.Shift=false);document.querySelector('#boost').addEventListener('pointerleave',()=>keys.Shift=false);
window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.code==='Space')fireCannon();if(!started&&e.key==='Enter')start()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
const stick=document.querySelector('#stick'),nub=document.querySelector('#nub');let stickId=null,stickX=0,stickY=0;stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function moveStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,limit=r.width*.34,d=Math.min(limit,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);stickX=Math.cos(a)*d/limit;stickY=Math.sin(a)*d/limit;nub.style.transform=`translate(${stickX*limit}px,${stickY*limit}px)`}function endStick(e){if(e.pointerId===stickId){stickId=null;stickX=stickY=0;nub.style.transform=''}}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);
const clock=new THREE.Clock();let waterTime=0;function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04);waterTime+=dt;if(started){let turn=(keys.a||keys.arrowleft?1:0)-(keys.d||keys.arrowright?1:0);turn+=stickX;yaw+=turn*dt*1.45;const throttle=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0)+(-stickY);const target=throttle>0?Math.min(16,throttle*11)*(keys.shift?1.55:1):throttle<0?Math.max(-5,throttle*5):0;speed=THREE.MathUtils.damp(speed,target,throttle?1.4:1.1,dt);const f=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));player.position.addScaledVector(f,speed*dt);player.rotation.y=yaw;player.position.y=Math.sin(waterTime*2.1)*.12;player.rotation.z=Math.sin(waterTime*1.6)*.025+turn*-.035;cooldown=Math.max(0,cooldown-dt);
const toEnemy=new THREE.Vector3().subVectors(player.position,enemy.position);toEnemy.y=0;const enemyDist=toEnemy.length();if(enemyHP>0){enemy.rotation.y=Math.atan2(toEnemy.x,toEnemy.z)+Math.sin(waterTime*.5)*.12;enemy.position.x+=Math.sin(enemy.rotation.y)*1.25*dt;enemy.position.z+=Math.cos(enemy.rotation.y)*1.25*dt;enemy.position.y=Math.sin(waterTime*2.2+1)*.1;if(enemyDist<150){enemyCooldown-=dt;if(enemyCooldown<=0){enemyFire();enemyCooldown=2.8+Math.random()*1.5}}}
for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.mesh.position.addScaledVector(p.vel,dt);p.life-=dt;if(p.enemy){if(p.mesh.position.distanceTo(player.position)<2.6){health=Math.max(0,health-17);document.querySelector('#health-fill').style.width=health+'%';if(health===0){health=100;gold=Math.max(0,gold-25);player.position.set(0,0,0);speed=0;notify('The Wren limps back to port. −25 doubloons.')}}}else if(enemyHP>0&&p.mesh.position.distanceTo(enemy.position)<3.2){enemyHP--;p.life=0;if(enemyHP===0){gold+=75;document.querySelector('#gold').textContent=gold;notify('Corsair ship defeated! +75 doubloons');scene.remove(enemy);enemyHP=-1}else notify(`Direct hit! Corsair hull ${enemyHP}/4`)}if(p.life<=0){scene.remove(p.mesh);projectiles.splice(i,1)}}
for(const island of [cay,...scene.children.filter(o=>o.userData.radius&&o!==cay)]){const d=Math.hypot(player.position.x-island.position.x,player.position.z-island.position.z);if(d<island.userData.radius+4){const dx=player.position.x-island.position.x,dz=player.position.z-island.position.z,l=Math.max(.1,Math.hypot(dx,dz));player.position.x=island.position.x+dx/l*(island.userData.radius+4);player.position.z=island.position.z+dz/l*(island.userData.radius+4);speed*=.4;if(island===cay&&!won){won=true;gold+=250;document.querySelector('#gold').textContent=gold;document.querySelector('#objective').innerHTML='✦ &nbsp;<b>Relic recovered!</b> &nbsp; Voyage complete';notify('The Lost Star is yours! +250 doubloons')}}}
const dist=Math.round(Math.hypot(300-player.position.x,-300-player.position.z));if(!won)document.querySelector('#objective').innerHTML=`◉ &nbsp;<b>Find Ember Cay</b> <span>· ${dist} m</span>`;document.querySelector('#compass').textContent=['N','NE','E','SE','S','SW','W','NW'][Math.round((yaw%(Math.PI*2)+Math.PI*2)%(Math.PI*2)/(Math.PI/4))%8];
if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show')}}
// rolling, shallow ocean swells
const attr=waterGeo.attributes.position;for(let i=0;i<attr.count;i++){const x=waterBase[i*3],z=waterBase[i*3+2];attr.array[i*3+1]=Math.sin(x*.027+waterTime*1.2)*.34+Math.sin(z*.04-waterTime*.8)*.21+Math.sin((x+z)*.013+waterTime*.6)*.14}attr.needsUpdate=true;waterGeo.computeVertexNormals();
const offset=new THREE.Vector3(0,9,-18).applyAxisAngle(new THREE.Vector3(0,1,0),yaw);const targetPos=player.position.clone().add(offset);camera.position.lerp(targetPos,1-Math.exp(-3.2*dt));const look=player.position.clone().add(new THREE.Vector3(0,1.4,0));camera.lookAt(look);renderer.render(scene,camera)}frame();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});

